# Construct the 30x30 tiled grid from its 5x5 motif-color layout, then apply matching-color connector rays.
import json
n=30
g=[[0]*n for _ in range(n)]
colors=[[3,2,2,3,0],[2,8,8,2,0],[3,2,2,3,0],[2,8,8,2,0],[0,0,0,0,0]]
starts=[1,8,15,22,29]
for tr,r0 in enumerate(starts):
  for tc,c0 in enumerate(starts):
    # The observed lattice has a 4-colored 5x5 frame and a 3x3 interior; last row/column are truncated.
    col=colors[tr][tc]
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<n and c<n and (dr in (0,4) or dc in (0,4)):
          g[r][c]=4
        elif r<n and c<n and col:
          g[r][c]=col
# For every repeated non-background motif, connect aligned occurrences through intervening separator strips.
# Interior coordinates for the first four complete tile rows/columns are 2..4, 9..11, 16..18, 23..25.
centers=[2,9,16,23]
# The dominant motif color 2 is the lattice's unmarked/base color; connect the minority motifs 3 and 8.
# 3: tile-row 0/2, columns 0/3; horizontal across columns and vertical across rows.
for r0 in (2,3,4,16,17,18):
  for c in (6,7,13,14,20,21): g[r0][c]=3
for r in (6,7,13,14):
  for c0 in (2,3,4,23,24,25): g[r][c0]=3
# 8: tile-row 1/3, columns 1/2.
for r in (9,10,11,23,24,25):
  for c in (13,14): g[r][c]=8
for r in (13,14):
  for c in (9,10,11,16,17,18): g[r][c]=8
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps(g,separators=(',',':')))

